import{_ as o,C as i,o as r,c as l,a6 as s,E as t}from"./chunks/framework.5dd0l9Wo.js";const k=JSON.parse('{"title":"API Testing","description":"Endpoint discovery, mass assignment, unused methods, and server-side parameter pollution in query strings and REST URLs.","frontmatter":{"title":"API Testing","description":"Endpoint discovery, mass assignment, unused methods, and server-side parameter pollution in query strings and REST URLs."},"headers":[],"relativePath":"api-testing/index.md","filePath":"api-testing/index.md"}'),d={name:"api-testing/index.md"};function p(c,e,u,h,g,m){const a=i("LabGroup"),n=i("TopicComplete");return r(),l("div",null,[e[0]||(e[0]=s('<h1 id="api-testing" tabindex="-1">API Testing <a class="header-anchor" href="#api-testing" aria-label="Permalink to &quot;API Testing&quot;">​</a></h1><p class="wd-section-lede">APIs expose the application&#39;s object model directly. That is convenient for clients and dangerous for defenders: fields, methods, and internal parameters that the UI never uses are often still accepted by the server.</p><div class="wd-callout"><p><strong>The model.</strong> A REST endpoint is a mapping from a request shape to a server-side operation. Test the <em>shape</em>, not just the values: add fields, change methods, duplicate parameters, move parameters between path, query, and body. The server may bind more of the request than the client sends.</p></div><h2 id="discovery" tabindex="-1">Discovery <a class="header-anchor" href="#discovery" aria-label="Permalink to &quot;Discovery&quot;">​</a></h2><ul><li><strong>Documentation:</strong> <code>/api</code>, <code>/swagger</code>, <code>/openapi.json</code>, <code>/docs</code>, <code>/graphql</code>.</li><li><strong>Method responses:</strong> <code>OPTIONS /api/user</code> often lists allowed methods.</li><li><strong>Client code:</strong> JavaScript bundles contain endpoint strings and parameter names.</li><li><strong>Error differences:</strong> a 404 vs 405 vs 400 tells you a route exists.</li><li><strong>Numeric ids and versioning:</strong> <code>/api/v1/</code>, <code>/api/internal/</code>.</li></ul>',5)),t(a,{ids:"api-testing-lab-exploiting-api-endpoint-using-documentation, api-testing-lab-exploiting-unused-api-endpoint"}),e[1]||(e[1]=s('<h2 id="mass-assignment" tabindex="-1">Mass assignment <a class="header-anchor" href="#mass-assignment" aria-label="Permalink to &quot;Mass assignment&quot;">​</a></h2><p>If the server binds the request body to an object without an allow-list, fields the client never sends are still writable: <code>role</code>, <code>isAdmin</code>, <code>price</code>, <code>discount</code>, <code>verified</code>.</p><div class="language-json vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;email&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;a@b.c&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;username&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;wiener&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;role&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;admin&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div>',3)),t(a,{ids:"api-testing-lab-exploiting-mass-assignment-vulnerability"}),e[2]||(e[2]=s(`<details class="details custom-block"><summary>🔬 Under the Hood: why the extra field is accepted</summary><p>Frameworks bind by reflection or by schema:</p><ul><li><strong>Spring</strong> <code>@ModelAttribute</code> and Jackson bind every matching setter.</li><li><strong>Rails</strong> <code>params.permit!</code> or <code>Model.new(params[:user])</code> without strong parameters.</li><li><strong>Django REST Framework</strong> serializers with <code>fields = &quot;__all__&quot;</code>.</li><li><strong>Node</strong> <code>Object.assign(user, req.body)</code>.</li></ul><p>The defence is an explicit input schema (allow-list), not a blocklist of dangerous field names. A blocklist will miss the next field the developer adds.</p></details><h2 id="server-side-parameter-pollution" tabindex="-1">Server-side parameter pollution <a class="header-anchor" href="#server-side-parameter-pollution" aria-label="Permalink to &quot;Server-side parameter pollution&quot;">​</a></h2><p>When the server embeds a user-supplied value into an internal request, delimiters can change the meaning of that request:</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>GET /api/products?category=gifts&amp;price=100</span></span>
<span class="line"><span>                              │</span></span>
<span class="line"><span>user controls category ───────┘</span></span>
<span class="line"><span>category=gifts%26price%3D0     → internal URL gains a second parameter</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br></div></div><p>The same applies to REST paths: a username inserted into <code>/api/users/&lt;name&gt;/profile</code> can contain <code>../</code> or <code>?</code> to reshape the internal request.</p>`,5)),t(a,{ids:"api-testing-lab-exploiting-server-side-parameter-pollution-in-query-string, api-testing-lab-exploiting-server-side-parameter-pollution-in-rest-url"}),e[3]||(e[3]=s('<details class="details custom-block"><summary>⚙️ Engine Variations: query parsing and duplicates</summary><ul><li><strong>PHP:</strong> <code>parse_str</code> keeps the last duplicate key; <code>[]</code> creates arrays.</li><li><strong>Express/qs:</strong> duplicates become arrays by default; <code>extended</code> parsing creates nested objects.</li><li><strong>Spring:</strong> <code>@RequestParam</code> takes the first value; <code>getParameterValues</code> returns all.</li><li><strong>Rails:</strong> <code>Rack::Utils.parse_nested_query</code> raises on conflicting types.</li><li><strong>Go:</strong> <code>URL.Query().Get()</code> returns the first value.</li></ul><p>Parameter pollution is the art of making the front-end validator and the back-end parser choose different occurrences of the same key.</p></details><div class="wd-callout wd-callout--warn"><p><strong>Defence.</strong> Define an explicit schema per endpoint and reject unknown fields. Authorise each field, not just the endpoint. Do not build internal URLs by string concatenation; use a URL builder with proper encoding and a fixed host. Disable unused HTTP methods at the router. Treat API docs as sensitive in production.</p></div>',2)),t(n,{"topic-id":"api-testing",label:"Mark API testing complete"})])}const _=o(d,[["render",p]]);export{k as __pageData,_ as default};
